#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> block_sums(max_threads + 1, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const int start = (tid * n) / nt;
        const int end   = ((tid + 1) * n) / nt;

        long long local_sum = 0;
        for (int i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = static_cast<int>(local_sum);
        }

        block_sums[tid + 1] = local_sum;

        #pragma omp barrier

        #pragma omp single
        {
            for (int t = 1; t < nt; ++t) {
                block_sums[t + 1] += block_sums[t];
            }
        }

        #pragma omp barrier

        const long long offset = block_sums[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + offset);
        }
    }
}
