void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    std::vector<long long> prefix(n);

    #pragma omp parallel for
    for (int i = 0; i < n; ++i) {
        prefix[i] = static_cast<long long>(x[i]);
    }

    for (int offset = 1; offset < n; offset <<= 1) {
        #pragma omp parallel for
        for (int i = n - 1; i >= offset; --i) {
            prefix[i] += prefix[i - offset];
        }
    }

    #pragma omp parallel for
    for (int i = 0; i < n; ++i) {
        output[i] = static_cast<int>(prefix[i]);
    }
}
